const fn = new Function(code + "\nreturn { createAccordion };");
const { createAccordion } = fn();
const acc = createAccordion(3);
if (acc.openCount() !== 0) throw new Error("Starts with all sections closed.");
acc.toggle(0);
if (!acc.isOpen(0) || acc.openCount() !== 1) throw new Error("toggle(0) opens section 0.");
acc.toggle(1);
if (acc.isOpen(0)) throw new Error("Opening section 1 closes section 0 (single-open).");
if (!acc.isOpen(1)) throw new Error("Section 1 is now open.");

