const acc = createAccordion(3);
acc.toggle(2);
acc.toggle(2);
if (acc.isOpen(2) || acc.openCount() !== 0) throw new Error("Toggling the open section must close it.");

const fn = new Function(code + "\nreturn { createAccordion };");
const { createAccordion } = fn();
